def parse():
    out = []
    for line in US_TEXT.strip().splitlines():
        st, names = line.split(":", 1)
        out += [("US", st.strip(), n.strip()) for n in names.split(";") if n.strip()]
    for line in UK_TEXT.strip().splitlines():
        nation, names = line.split(":", 1)
        out += [("UK", nation.strip(), n.strip()) for n in names.split(";") if n.strip()]
    return out
